mapper.select:
select mn.*, dmc2.Dm_region_name as dmParentRegionName, pro.p_Name as pName from drawing_item mn left join Drawing_Management_Catalogue dmc on mn.di_region_group = dmc.Dm_Id left join Drawing_Management_Catalogue dmc2 on dmc.dm_parent_id = dmc2.Dm_Id left join pre_project pro on pro.P_Id = mn.p_id
and mn.p_id = #{params.pId}
and mn.di_region_group in
#{item}
and mn.di_region_name like concat('%',#{params.diRegionName},'%')
and mn.di_region_code like concat('%',#{params.diRegionCode},'%')
and mn.state = #{params.state}
order by mn.create_time desc
